import{_ as a,o as t,c as r,a3 as s}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Frosted Glass Theme Manager","description":"Notes on the Frosted Glass Theme Manager and the tested UIX test variant.","frontmatter":{"title":"Frosted Glass Theme Manager","description":"Notes on the Frosted Glass Theme Manager and the tested UIX test variant."},"headers":[],"relativePath":"en/collection/frosted-glass-manager/index.md","filePath":"en/collection/frosted-glass-manager/index.md","lastUpdated":1793123358000}'),o={name:"en/collection/frosted-glass-manager/index.md"};function i(n,e,l,d,g,h){return t(),r("div",null,[...e[0]||(e[0]=[s('<p><a id="current-focus"></a></p><h1 id="frosted-glass-theme-manager" tabindex="-1">Frosted Glass Theme Manager <a class="header-anchor" href="#frosted-glass-theme-manager" aria-label="Permalink to &quot;Frosted Glass Theme Manager {#frosted-glass-theme-manager}&quot;">​</a></h1><p>The Frosted Glass Theme Manager is a home assistant custom integration for generating customized Frosted Glass theme files. Colors and background images can be set via the Home Assistant interface.</p><div class="warning custom-block"><p class="custom-block-title">Unofficial note</p><p>This page is not official documentation of the project. The original repository remains authoritative.</p></div><table tabindex="0"><thead><tr><th>field</th><th>Value</th></tr></thead><tbody><tr><td>Original project</td><td><a href="https://github.com/wessamlauf/frosted-glass-manager" target="_blank" rel="noreferrer">wessamlauf/frosted-glass-manager</a></td></tr><tr><td>Fork with UIX test variant</td><td><a href="https://github.com/rockbaer2007/frosted-glass-manager/tree/experiment/uix-theme-manager" target="_blank" rel="noreferrer">rockbaer2007/frosted-glass-manager</a></td></tr><tr><td>Pull Request</td><td><a href="https://github.com/wessamlauf/frosted-glass-manager/pull/15" target="_blank" rel="noreferrer">wessamlauf/frosted-glass-manager#15</a></td></tr><tr><td>Category</td><td>HA integrations</td></tr></tbody></table><h2 id="original-manager" tabindex="-1">Original Manager <a class="header-anchor" href="#original-manager" aria-label="Permalink to &quot;Original Manager {#original-manager}&quot;">​</a></h2><p>The original manager creates Frosted Glass theme files for normal use with card-mod.</p><p><a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=wessamlauf&amp;repository=frosted-glass-manager&amp;category=integration" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/hacs_repository.svg" alt="Open Frosted Glass Theme Manager in HACS"></a></p><p>Repositories:</p><ul><li><a href="https://github.com/wessamlauf/frosted-glass-manager" target="_blank" rel="noreferrer">wessamlauf/frosted-glass-manager</a></li></ul><h2 id="uix-testvariante" tabindex="-1">UIX test variant <a class="header-anchor" href="#uix-testvariante" aria-label="Permalink to &quot;UIX test variant {#uix-testvariante}&quot;">​</a></h2><p>For installations that use UIX instead of card-mod, there is a tested UIX working version as a fork.</p><p><a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=frosted-glass-manager&amp;category=integration" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/hacs_repository.svg" alt="Open Frosted Glass UIX Theme Manager in HACS"></a></p><p>Repositories:</p><ul><li><a href="https://github.com/rockbaer2007/frosted-glass-manager/tree/experiment/uix-theme-manager" target="_blank" rel="noreferrer">Frosted Glass UIX Theme Manager</a></li></ul><p>The UIX test variant uses its own Home Assistant integration identifier:</p><ul><li><code>frosted_glass_uix_manager</code></li></ul><p>It creates its own theme files and therefore does not conflict with the normal Frosted Glass file names:</p><ul><li><code>Frosted Glass UIX Custom.yaml</code></li><li><code>Frosted Glass UIX Custom Lite.yaml</code></li></ul><p>The standard backgrounds are supplied locally and copied to Home Assistant when started:</p><ul><li><code>config/www/frosted-glass-uix/frosted-glass-light-background.jpg</code></li><li><code>config/www/frosted-glass-uix/frosted-glass-dark-background.jpg</code></li></ul><p>They are integrated into the generated themes via <code>/local/frosted-glass-uix/...</code>. This means that the standard optics are not dependent on an external CDN.</p><h2 id="hinweis" tabindex="-1">Note <a class="header-anchor" href="#hinweis" aria-label="Permalink to &quot;Note {#hinweis}&quot;">​</a></h2><p>The UIX test variant has already been tested in practice, but remains an experimental variant. For general questions about the original project, you should continue to use the original repository.</p>',24)])])}const p=a(o,[["render",i]]);export{c as __pageData,p as default};
